<script setup>import LoadingSpinner from './LoadingSpinner.vue'; defineProps({ cliente: { type: Object, required: true }, procesando: { type: Boolean, default: false } }); defineEmits(['confirmar', 'cancelar'])</script>
<template><div class="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/50 p-4"><section role="dialog" aria-modal="true" aria-labelledby="confirm-title" class="w-full max-w-md rounded-2xl bg-white p-6 shadow-xl"><h2 id="confirm-title" class="text-xl font-bold">Eliminar cliente</h2><p class="mt-3 text-slate-600">¿Deseas eliminar a <strong>{{ cliente.nombre }}</strong>? Esta acción no se puede deshacer.</p><div class="mt-6 flex justify-end gap-3"><button type="button" :disabled="procesando" class="rounded-lg border border-slate-300 px-4 py-2" @click="$emit('cancelar')">Cancelar</button><button type="button" :disabled="procesando" class="inline-flex items-center gap-2 rounded-lg bg-red-700 px-4 py-2 text-white disabled:opacity-60" @click="$emit('confirmar')"><LoadingSpinner v-if="procesando"/>{{ procesando ? 'Eliminando...' : 'Sí, eliminar' }}</button></div></section></div></template>
